"""Global visual preproduction policy; no assets are generated by this module."""
def apply(catalog):
    catalog['workflow']='Tema e estilos → materiais e roteiro → moodboard visual aprovado → storyboard visual aprovado → amostra de 10 segundos → aprovação → vídeo completo.'
    for style in catalog['styles']:
        style['preset']['firstDelivery']=['roteiro','moodboard visual para aprovação','storyboard visual para aprovação','vídeo de 10 segundos após aprovação da pré-produção']
        style['preset']['approvalGate']='Gerar e apresentar moodboard; após aprovação, gerar storyboard completo para aprovação. Só gerar a amostra após as duas aprovações explícitas. Não produzir o vídeo completo antes da aprovação da amostra de 10 segundos.'
